ON CONFLICT (part_number) DO UPDATE SET
 name=excluded.name,description=excluded.description,technical_group=excluded.technical_group,
 source_name=excluded.source_name,source_url=excluded.source_url,source_note=excluded.source_note,
 verification_status=excluded.verification_status,is_active=true,source_accessed_at=now(),
 image_url=coalesce(excluded.image_url,public.part_catalog.image_url),specifications=excluded.specifications,
 application_type=excluded.application_type,application_evidence=excluded.application_evidence,
 application_source_url=excluded.application_source_url,updated_at=now();